ALTER TABLE wb.release_batch ADD COLUMN assets_revision bigint NOT NULL DEFAULT 1 CHECK(assets_revision>0);
CREATE TABLE wb.asset_root(project_id text NOT NULL,batch_id text NOT NULL,asset_id text NOT NULL,current_revision bigint NOT NULL CHECK(current_revision>0),PRIMARY KEY(project_id,batch_id,asset_id),FOREIGN KEY(project_id,batch_id) REFERENCES wb.release_batch);
CREATE TABLE wb.asset_revision(project_id text NOT NULL,batch_id text NOT NULL,asset_id text NOT NULL,revision bigint NOT NULL CHECK(revision>0),kind text NOT NULL CHECK(kind='milestone'),title text NOT NULL CHECK(btrim(title)<>''),due_date date NOT NULL CHECK(isfinite(due_date)),description text NOT NULL DEFAULT '',owner_display text NOT NULL DEFAULT '',state text NOT NULL CHECK(state IN('ACTIVE','RETIRED')),scope_level text NOT NULL CHECK(scope_level IN('BATCH_WIDE','EXACT_RELATIONS')),created_release_date date NOT NULL,scope_link_count integer NOT NULL CHECK(scope_link_count BETWEEN 0 AND 200),actor text NOT NULL,reason text NOT NULL CHECK(btrim(reason)<>''),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(project_id,batch_id,asset_id,revision),FOREIGN KEY(project_id,batch_id,asset_id) REFERENCES wb.asset_root DEFERRABLE INITIALLY DEFERRED);
ALTER TABLE wb.asset_root ADD FOREIGN KEY(project_id,batch_id,asset_id,current_revision) REFERENCES wb.asset_revision(project_id,batch_id,asset_id,revision) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE wb.asset_brv_link(project_id text NOT NULL,batch_id text NOT NULL,asset_id text NOT NULL,revision bigint NOT NULL,requirement_id text NOT NULL,version_id text NOT NULL,PRIMARY KEY(project_id,batch_id,asset_id,revision,requirement_id,version_id),FOREIGN KEY(project_id,batch_id,asset_id,revision) REFERENCES wb.asset_revision,FOREIGN KEY(project_id,batch_id,requirement_id,version_id) REFERENCES wb.batch_requirement_version);
CREATE TABLE wb.asset_brvs_link(project_id text NOT NULL,batch_id text NOT NULL,asset_id text NOT NULL,revision bigint NOT NULL,requirement_id text NOT NULL,version_id text NOT NULL,sst_id text NOT NULL,PRIMARY KEY(project_id,batch_id,asset_id,revision,requirement_id,version_id,sst_id),FOREIGN KEY(project_id,batch_id,asset_id,revision) REFERENCES wb.asset_revision,FOREIGN KEY(project_id,batch_id,requirement_id,version_id,sst_id) REFERENCES wb.batch_requirement_version_sst);
CREATE TABLE wb.asset_outbox(event_id text PRIMARY KEY,project_id text NOT NULL,batch_id text NOT NULL,asset_id text NOT NULL,revision bigint NOT NULL,event_type text NOT NULL CHECK(event_type IN('workbench.asset.created','workbench.asset.updated','workbench.asset.retired','workbench.asset.restored')),request_ref text NOT NULL,audit_id bigint NOT NULL REFERENCES wb.audit,UNIQUE(project_id,batch_id,asset_id,revision),FOREIGN KEY(project_id,batch_id,asset_id,revision) REFERENCES wb.asset_revision);
CREATE TABLE wb.asset_request_result(project_id text NOT NULL,actor text NOT NULL,request_id text NOT NULL,result jsonb NOT NULL,PRIMARY KEY(project_id,actor,request_id),FOREIGN KEY(project_id,actor,request_id) REFERENCES wb.request_log);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['asset_root','asset_revision','asset_brv_link','asset_brvs_link','asset_outbox','asset_request_result'] LOOP EXECUTE format('ALTER TABLE wb.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY read_scope ON wb.%I FOR SELECT USING(wb.allowed(project_id,false))',t); EXECUTE format('CREATE POLICY insert_scope ON wb.%I FOR INSERT WITH CHECK(wb.allowed(project_id,true))',t); END LOOP; FOREACH t IN ARRAY ARRAY['asset_revision','asset_brv_link','asset_brvs_link','asset_outbox','asset_request_result'] LOOP EXECUTE format('CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON wb.%I FOR EACH ROW EXECUTE FUNCTION wb.reject_history_change()',t); END LOOP; END $$;
CREATE POLICY root_update ON wb.asset_root FOR UPDATE USING(wb.allowed(project_id,true)) WITH CHECK(wb.allowed(project_id,true));
CREATE FUNCTION wb.asset_root_changed() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,wb AS $$ BEGIN IF TG_OP='INSERT' AND NEW.current_revision<>1 THEN RAISE EXCEPTION 'ASSET_INITIAL_REVISION_INVALID' USING ERRCODE='23514'; END IF; IF TG_OP='UPDATE' AND (NEW.project_id<>OLD.project_id OR NEW.batch_id<>OLD.batch_id OR NEW.asset_id<>OLD.asset_id OR NEW.current_revision<>OLD.current_revision+1) THEN RAISE EXCEPTION 'ASSET_REVISION_INVALID' USING ERRCODE='23514'; END IF; UPDATE wb.release_batch SET assets_revision=assets_revision+1 WHERE project_id=NEW.project_id AND batch_id=NEW.batch_id; RETURN NEW; END $$;
CREATE TRIGGER asset_root_changed AFTER INSERT OR UPDATE ON wb.asset_root FOR EACH ROW EXECUTE FUNCTION wb.asset_root_changed();
CREATE FUNCTION wb.asset_version_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,wb AS $$ DECLARE links bigint; BEGIN SELECT (SELECT count(*) FROM wb.asset_brv_link WHERE project_id=NEW.project_id AND batch_id=NEW.batch_id AND asset_id=NEW.asset_id AND revision=NEW.revision)+(SELECT count(*) FROM wb.asset_brvs_link WHERE project_id=NEW.project_id AND batch_id=NEW.batch_id AND asset_id=NEW.asset_id AND revision=NEW.revision) INTO links; IF links<>NEW.scope_link_count OR NOT EXISTS(SELECT 1 FROM wb.asset_root WHERE project_id=NEW.project_id AND batch_id=NEW.batch_id AND asset_id=NEW.asset_id AND current_revision=NEW.revision) OR (NEW.revision>1 AND NOT EXISTS(SELECT 1 FROM wb.asset_revision WHERE project_id=NEW.project_id AND batch_id=NEW.batch_id AND asset_id=NEW.asset_id AND revision=NEW.revision-1)) OR (NEW.scope_level='EXACT_RELATIONS' AND links=0) OR (NEW.scope_level='BATCH_WIDE' AND links<>0) OR NOT EXISTS(SELECT 1 FROM wb.asset_outbox o JOIN wb.audit a ON a.audit_id=o.audit_id WHERE o.project_id=NEW.project_id AND o.batch_id=NEW.batch_id AND o.asset_id=NEW.asset_id AND o.revision=NEW.revision AND a.object_id=NEW.asset_id AND a.actor=NEW.actor AND a.request_id=o.request_ref AND a.project_id=NEW.project_id) THEN RAISE EXCEPTION 'ASSET_SCOPE_AUDIT_OUTBOX_REQUIRED' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER asset_version_complete AFTER INSERT ON wb.asset_revision DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION wb.asset_version_complete();

DROP POLICY read_scope ON wb.asset_request_result;
DROP POLICY insert_scope ON wb.asset_request_result;
CREATE POLICY request_result_scope ON wb.asset_request_result USING(wb.allowed(project_id,false) AND actor=current_setting('wb.principal',true)) WITH CHECK(wb.allowed(project_id,true) AND actor=current_setting('wb.principal',true));

CREATE FUNCTION wb.asset_links_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,wb AS $$ DECLARE expected integer; actual bigint; BEGIN SELECT scope_link_count INTO expected FROM wb.asset_revision WHERE project_id=NEW.project_id AND batch_id=NEW.batch_id AND asset_id=NEW.asset_id AND revision=NEW.revision; SELECT (SELECT count(*) FROM wb.asset_brv_link WHERE project_id=NEW.project_id AND batch_id=NEW.batch_id AND asset_id=NEW.asset_id AND revision=NEW.revision)+(SELECT count(*) FROM wb.asset_brvs_link WHERE project_id=NEW.project_id AND batch_id=NEW.batch_id AND asset_id=NEW.asset_id AND revision=NEW.revision) INTO actual; IF expected IS NULL OR expected<>actual THEN RAISE EXCEPTION 'IMMUTABLE_ASSET_SCOPE' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER asset_links_complete AFTER INSERT ON wb.asset_brv_link DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION wb.asset_links_complete();
CREATE CONSTRAINT TRIGGER asset_links_complete AFTER INSERT ON wb.asset_brvs_link DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION wb.asset_links_complete();
